begin;
create temp table checks(label text);
create function pg_temp.check(ok boolean,label text)returns void language plpgsql as $$begin if ok is not true then raise exception 'FAIL: %',label;end if;insert into checks values(label);end$$;
create temp table fixture(property_id uuid,other_property uuid,actor uuid,record_id uuid,review_id uuid);
insert into fixture values(gen_random_uuid(),gen_random_uuid(),'11111111-1111-1111-1111-111111111111',gen_random_uuid(),gen_random_uuid());
insert into public.properties(id,name,org_id)select property_id,'Delivery evidence SQL fixture','22222222-2222-2222-2222-222222222222'::uuid from fixture union all select other_property,'Other delivery evidence SQL fixture','22222222-2222-2222-2222-222222222222'::uuid from fixture;
create function pg_temp.source_input()returns jsonb language sql as $$select jsonb_build_object('sourceName','delivery-record.md','sourceFormat','markdown','sourceOrigin','client_project_report','sourceText','# Client report
Exact original evidence; unknown checks remain untested.','targetLabel','Synthetic local WordPress target','targetPurpose','local','sourceRevision','fixture-source-v1','observedAt',null,'contentSource','Client project only','editorOwner','','briefId',null,'parentId',null)$$;
create function pg_temp.review_input(p_record uuid,p_action text default 'review')returns jsonb language sql as $$
 select jsonb_build_object('recordId',r.id,'sourceHash',r.source_hash,'expectedReviewId',(select d.id from public.siteforge_delivery_reviews d where d.record_id=r.id order by d.review_sequence desc limit 1),'action',p_action,'reason','Review synthetic reported evidence')||case when p_action='review'then jsonb_build_object('checks',(select jsonb_agg(jsonb_build_object('category',c,'status','not_run','evidence','','observedAt',null,'notes',''))from unnest(array['design_routes','editing','preview_revisions','facts_inventory','inquiry_integrations','accessibility_content','imports_redirects','package_runtime','domain_discovery','recovery','maintenance'])c))else '{}'::jsonb end from public.siteforge_delivery_records r where r.id=p_record
$$;
create function pg_temp.reject_delivery_review()returns trigger language plpgsql as $$begin if new.action='site.delivery.reviewed'then raise exception 'Fixture: action history unavailable';end if;return new;end$$;
do $$declare f fixture;r jsonb;v_input jsonb;v_review jsonb;v_bad jsonb;child uuid:=gen_random_uuid();unknown_version uuid:=gen_random_uuid();v_new uuid;begin select *into f from fixture;v_input:=pg_temp.source_input();
 perform pg_temp.check(not has_table_privilege('authenticated','public.siteforge_delivery_records','SELECT')and not has_table_privilege('anon','public.siteforge_delivery_reviews','SELECT')and not has_function_privilege('authenticated','public.review_siteforge_delivery(uuid,uuid,uuid,jsonb)','EXECUTE'),'source evidence and reviews are private');
 perform pg_temp.check(public.record_siteforge_delivery(f.record_id,f.property_id,gen_random_uuid(),v_input)->>'state'='forbidden','source intake requires a current property actor');
 r:=public.record_siteforge_delivery(f.record_id,f.property_id,f.actor,v_input);perform pg_temp.check(r->>'state'='saved'and(select input->>'sourceText'=v_input->>'sourceText'and input->'observedAt'='null'::jsonb from public.siteforge_delivery_records where id=f.record_id),'retains exact source and unknown observation date without substituting import time');
 perform pg_temp.check(public.record_siteforge_delivery(f.record_id,f.property_id,f.actor,v_input)->>'state'='replayed'and public.record_siteforge_delivery(f.record_id,f.property_id,f.actor,v_input||'{"sourceText":"Altered original evidence is not the same request"}')->>'state'='request_conflict','intake lost replies replay exact source identity');
 perform pg_temp.check((select position('Exact original evidence'in request::text)=0 and result->'sourceVerified'='false'and result->'deliveryConfirmed'='false'from public.shared_action_events where id=f.record_id),'shared records do not expose original source or fabricate verified delivery');
 perform pg_temp.check(public.record_siteforge_delivery(child,f.other_property,f.actor,v_input||jsonb_build_object('parentId',f.record_id))->>'state'='parent_unavailable','source ancestry cannot cross properties');
 perform pg_temp.check(public.record_siteforge_delivery(child,f.property_id,f.actor,v_input||jsonb_build_object('briefId',gen_random_uuid()))->>'state'='brief_unavailable','unavailable related brief rejected');
 r:=public.record_siteforge_delivery(child,f.property_id,f.actor,v_input||jsonb_build_object('parentId',f.record_id,'sourceRevision','fixture-v2'));
 perform pg_temp.check(r->>'state'='saved'and(select parent_id=f.record_id from public.siteforge_delivery_records where id=child),'revised source retains an immutable original parent');
 begin perform public.record_siteforge_delivery(gen_random_uuid(),f.property_id,f.actor,v_input||jsonb_build_object('sourceText',repeat('🌿',70000)));raise exception 'expected bounded source';exception when others then if sqlerrm='expected bounded source'then raise;end if;end;
 perform pg_temp.check((select count(*)=2 from public.siteforge_delivery_records where property_id=f.property_id),'oversized multibyte source is rejected as a whole');
 v_review:=pg_temp.review_input(f.record_id);
 perform pg_temp.check(public.review_siteforge_delivery(f.review_id,f.property_id,f.actor,jsonb_set(v_review,'{sourceHash}','"wrong"'))->>'state'='source_changed','review is bound to exact original source hash');
 begin perform public.review_siteforge_delivery(f.review_id,f.property_id,f.actor,jsonb_set(v_review,'{checks}',(v_review->'checks')-0));raise exception 'expected all categories';exception when others then if sqlerrm='expected all categories'then raise;end if;end;
 v_bad:=jsonb_set(v_review,'{checks,0,category}','"editing"');begin perform public.review_siteforge_delivery(f.review_id,f.property_id,f.actor,v_bad);raise exception 'expected unique categories';exception when others then if sqlerrm='expected unique categories'then raise;end if;end;
 perform pg_temp.check(not exists(select 1 from public.siteforge_delivery_reviews where record_id=f.record_id),'partial and duplicate checklists cannot become complete reviews');
 v_bad:=jsonb_set(v_review,'{checks,0,status}','"passed"');begin perform public.review_siteforge_delivery(f.review_id,f.property_id,f.actor,v_bad);raise exception 'expected dated evidence';exception when others then if sqlerrm='expected dated evidence'then raise;end if;end;
 v_bad:=jsonb_set(v_review,'{checks,1,status}','"out_of_scope"');begin perform public.review_siteforge_delivery(f.review_id,f.property_id,f.actor,v_bad);raise exception 'expected exclusion reason';exception when others then if sqlerrm='expected exclusion reason'then raise;end if;end;
 perform pg_temp.check(not exists(select 1 from public.siteforge_delivery_reviews where record_id=f.record_id),'unsupported passes and unexplained exclusions remain unrecorded');
 perform public.record_siteforge_delivery(unknown_version,f.property_id,f.actor,v_input||'{"sourceRevision":""}');v_bad:=pg_temp.review_input(unknown_version);v_bad:=jsonb_set(jsonb_set(jsonb_set(v_bad,'{checks,0,status}','"passed"'),'{checks,0,evidence}','"checks/routes.txt"'),'{checks,0,observedAt}',to_jsonb(current_date::text));
 begin perform public.review_siteforge_delivery(gen_random_uuid(),f.property_id,f.actor,v_bad);raise exception 'expected tested version';exception when others then if sqlerrm='expected tested version'then raise;end if;end;
 perform pg_temp.check(public.review_siteforge_delivery(gen_random_uuid(),f.property_id,f.actor,pg_temp.review_input(unknown_version))->>'state'='saved','unknown-version source can retain an honest untested review, never a pass');
 v_review:=jsonb_set(jsonb_set(jsonb_set(v_review,'{checks,0,status}','"passed"'),'{checks,0,evidence}','"checks/routes.txt"'),'{checks,0,observedAt}',to_jsonb(current_date::text));
 perform pg_temp.check(public.review_siteforge_delivery(f.review_id,f.property_id,f.actor,v_review)->>'state'='saved','complete reported review is saved with dated evidence and exact version');
 perform pg_temp.check(public.review_siteforge_delivery(f.review_id,f.property_id,f.actor,v_review)->>'state'='replayed'and public.review_siteforge_delivery(f.review_id,f.property_id,f.actor,v_review||'{"reason":"Changed decision"}')->>'state'='request_conflict','review retry cannot change its original decision');
 perform pg_temp.check(public.review_siteforge_delivery(gen_random_uuid(),f.property_id,f.actor,v_review)->>'state'='review_changed','stale review cannot overwrite a newer decision');
 v_new:=gen_random_uuid();v_bad:=pg_temp.review_input(f.record_id);create trigger reject_delivery_review before insert on public.shared_action_events for each row execute function pg_temp.reject_delivery_review();
 begin perform public.review_siteforge_delivery(v_new,f.property_id,f.actor,v_bad);raise exception 'expected atomic history';exception when others then if sqlerrm='expected atomic history'then raise;end if;end;
 drop trigger reject_delivery_review on public.shared_action_events;
 perform pg_temp.check(not exists(select 1 from public.siteforge_delivery_reviews where id=v_new),'shared-history failure rolls back the review');
 v_bad:=jsonb_set(jsonb_set(pg_temp.review_input(f.record_id),'{checks,0,status}','"failed"'),'{checks,0,notes}','"Correction: route comparison was incomplete"');perform public.review_siteforge_delivery(v_new,f.property_id,f.actor,v_bad);
 perform pg_temp.check((select input->'checks'->0->>'status'='passed'from public.siteforge_delivery_reviews where id=f.review_id)and(select input->'checks'->0->>'status'='failed'from public.siteforge_delivery_reviews where id=v_new),'corrected report retains the original passed claim and the failed correction separately');
 perform public.review_siteforge_delivery(gen_random_uuid(),f.property_id,f.actor,pg_temp.review_input(f.record_id,'withdraw'));
 r:=public.read_siteforge_delivery_records(f.property_id,f.actor,null,f.record_id);perform pg_temp.check(r->'selected'->'latestReview'->>'action'='withdraw'and jsonb_array_length(r->'reviews')=3,'withdrawal never falls back to an earlier reported pass');
 perform pg_temp.check(public.review_siteforge_delivery(gen_random_uuid(),f.property_id,f.actor,pg_temp.review_input(f.record_id,'withdraw'))->>'state'='state_changed','withdrawn review cannot be withdrawn again as a new success');
 begin update public.siteforge_delivery_records set input='{}'where id=f.record_id;raise exception 'expected retained source';exception when others then if sqlerrm='expected retained source'then raise;end if;end;
 begin delete from public.siteforge_delivery_reviews where id=f.review_id;raise exception 'expected retained review';exception when others then if sqlerrm='expected retained review'then raise;end if;end;
 perform pg_temp.check((select input->>'sourceText'=v_input->>'sourceText'from public.siteforge_delivery_records where id=f.record_id)and exists(select 1 from public.siteforge_delivery_reviews where id=f.review_id),'original source and reviews cannot be rewritten or silently deleted');
 perform pg_temp.check(public.read_siteforge_delivery_records(f.other_property,f.actor,null,f.record_id)->>'state'='not_found','exact source reads cannot cross property');
 update public.profiles set org_id=null where id=f.actor;
 perform pg_temp.check(public.read_siteforge_delivery_records(f.property_id,f.actor)->>'state'='forbidden'and public.record_siteforge_delivery(f.record_id,f.property_id,f.actor,v_input)->>'state'='forbidden'and public.review_siteforge_delivery(f.review_id,f.property_id,f.actor,v_review)->>'state'='forbidden','source and decision replay recheck current organization');
 update public.profiles set org_id='22222222-2222-2222-2222-222222222222'where id=f.actor;
end$$;
do $$declare f fixture;i integer;r jsonb;cursor_id uuid;seen uuid[]:='{}';expected bigint;begin select *into f from fixture;
 for i in 1..1005 loop perform public.record_siteforge_delivery(gen_random_uuid(),f.property_id,f.actor,pg_temp.source_input()||jsonb_build_object('sourceName','retained-report-'||i));end loop;
 select count(*)into expected from public.siteforge_delivery_records where property_id=f.property_id;
 loop r:=public.read_siteforge_delivery_records(f.property_id,f.actor,cursor_id);select seen||array_agg((v->>'id')::uuid)into seen from jsonb_array_elements(r->'records')v;cursor_id:=(r->>'nextCursor')::uuid;exit when cursor_id is null;end loop;
 perform pg_temp.check(cardinality(seen)=expected and(select count(distinct id)=expected from unnest(seen)id),'source history reaches every record beyond1000');
 for i in 1..24 loop perform public.review_siteforge_delivery(gen_random_uuid(),f.property_id,f.actor,pg_temp.review_input(f.record_id));end loop;
 seen:='{}';cursor_id:=null;loop r:=public.read_siteforge_delivery_records(f.property_id,f.actor,null,f.record_id,cursor_id);select seen||array_agg((v->>'id')::uuid)into seen from jsonb_array_elements(r->'reviews')v;cursor_id:=(r->>'nextReviewCursor')::uuid;exit when cursor_id is null;end loop;
 perform pg_temp.check(cardinality(seen)=27 and(select count(distinct id)=27 from unnest(seen)id),'review history includes every correction and withdrawal beyond one page');
 perform pg_temp.check(public.read_siteforge_delivery_records(f.property_id,f.actor,gen_random_uuid())->>'state'='cursor_changed','unrelated record cursors are rejected');
end$$;
select count(*)as passed_assertions from checks;
rollback;
